-- Дополнительные постройки (страница /extras/ и раздел на главной): направления — бани, модульные дома, беседки, площадки.
-- data: slug, name, lead (коротко, для главной), text, points (пункты, по одному в строке), image и works — примеры работ
-- [{ image, title, note }]; у текстов есть кыргызские пары *_ky. Цены нет — обсуждается при обращении.
-- Начальные записи — демо: фото Pexels, тексты-образцы.
CREATE TABLE extras (
  id         serial PRIMARY KEY,
  position   integer NOT NULL DEFAULT 0,
  data       jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);
INSERT INTO extras (position, data) VALUES
  (0, '{"slug": "bani", "name": "Бани и сауны", "name_ky": "Мончолор жана сауналар", "image": "https://images.pexels.com/photos/8092430/pexels-photo-8092430.jpeg?auto=compress&cs=tinysrgb&w=1000", "lead": "Русская баня или финская сауна — отдельно стоящая или под одной крышей с домом.", "lead_ky": "Орус мончосу же фин саунасы — өзүнчө же үй менен бир чатырдын астында.", "text": "Строим бани и сауны на том же металлическом каркасе, что и дома: без усадки, с паро- и теплоизоляцией и отделкой натуральным деревом. Подберём печь, планировку и комнату отдыха под ваш участок.", "text_ky": "Мончолорду жана сауналарды үйлөр сыяктуу эле металл каркаста курабыз: отурбайт, буу жана жылуулук изоляциясы менен, табигый жыгач жасалгасы менен. Жериңизге ылайык меш, пландоо жана эс алуу бөлмөсүн тандайбыз.", "points": "Парная, моечная и комната отдыха\nДровяная или электрическая печь\nОтделка натуральным деревом\nТерраса и купель — по желанию", "points_ky": "Буу бөлмө, жуунуучу жай жана эс алуу бөлмөсү\nОтун же электр меш\nТабигый жыгач менен жасалга\nТерраса жана суу бассейни — каалоо боюнча", "works": [{"image": "https://images.pexels.com/photos/19943132/pexels-photo-19943132.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Баня в горах", "title_ky": "Тоодогу мончо", "note": "демо-фото", "note_ky": "демо-сүрөт"}, {"image": "https://images.pexels.com/photos/5979569/pexels-photo-5979569.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Сауна с панорамным окном", "title_ky": "Панорамалык терезелүү сауна", "note": "демо-фото", "note_ky": "демо-сүрөт"}]}'),
  (1, '{"slug": "modular", "name": "Модульные дома", "name_ky": "Модулдук үйлөр", "image": "https://images.pexels.com/photos/30484316/pexels-photo-30484316.jpeg?auto=compress&cs=tinysrgb&w=1000", "lead": "Компактные дома из готовых модулей: быстро собрать, легко расширить.", "lead_ky": "Даяр модулдардан компакттуу үйлөр: тез чогултулат, оңой кеңейтилет.", "text": "Модульный дом собираем из блоков на металлическом каркасе. Подходит для гостевого дома, офиса на участке, жилья для персонала или базы отдыха. Модули можно добавлять, когда понадобится больше места.", "text_ky": "Модулдук үйдү металл каркастагы блоктордон чогултабыз. Конок үйү, участоктогу кеңсе, кызматкерлер үчүн турак жай же эс алуу базасы үчүн ылайыктуу. Орун көбүрөөк керек болгондо модулдарды кошсо болот.", "points": "Гостевой дом или домик для персонала\nБазы отдыха и глэмпинги\nУтепление и отделка как в основном доме\nМожно расширить новыми модулями", "points_ky": "Конок үйү же кызматкерлер үчүн үй\nЭс алуу базалары жана глэмпингдер\nНегизги үйдөгүдөй жылуулоо жана жасалга\nЖаңы модулдар менен кеңейтсе болот", "works": [{"image": "https://images.pexels.com/photos/4266488/pexels-photo-4266488.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Гостевой домик", "title_ky": "Конок үйү", "note": "демо-фото", "note_ky": "демо-сүрөт"}, {"image": "https://images.pexels.com/photos/19278915/pexels-photo-19278915.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Домик для отдыха", "title_ky": "Эс алуу үйү", "note": "демо-фото", "note_ky": "демо-сүрөт"}]}'),
  (2, '{"slug": "gazebos", "name": "Беседки и навесы", "name_ky": "Беседкалар жана навестер", "image": "https://images.pexels.com/photos/13871253/pexels-photo-13871253.jpeg?auto=compress&cs=tinysrgb&w=1000", "lead": "Беседки, перголы, навесы для машин и зоны барбекю.", "lead_ky": "Беседкалар, перголалар, унаа үчүн навестер жана барбекю аймактары.", "text": "Делаем беседки и навесы на металлическом каркасе с деревянной отделкой — в том же стиле, что и дом. Открытые и закрытые, с мангальной зоной, освещением и местами для отдыха.", "text_ky": "Беседкаларды жана навестерди жыгач жасалгалуу металл каркаста үй менен бир стилде жасайбыз. Ачык жана жабык, мангал аймагы, жарык жана эс алуучу орундар менен.", "points": "Открытые и остеклённые беседки\nПерголы и навесы для машин\nЗоны барбекю с мангалом или печью\nОсвещение и электрика", "points_ky": "Ачык жана айнектелген беседкалар\nПерголалар жана унаа үчүн навестер\nМангал же меш менен барбекю аймактары\nЖарык жана электр", "works": [{"image": "https://images.pexels.com/photos/18090276/pexels-photo-18090276.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Большая беседка для отдыха", "title_ky": "Эс алуу үчүн чоң беседка", "note": "демо-фото", "note_ky": "демо-сүрөт"}, {"image": "https://images.pexels.com/photos/7174111/pexels-photo-7174111.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Беседка в саду", "title_ky": "Бактагы беседка", "note": "демо-фото", "note_ky": "демо-сүрөт"}]}'),
  (3, '{"slug": "playgrounds", "name": "Детские и спортивные площадки", "name_ky": "Балдар жана спорт аянтчалары", "image": "https://images.pexels.com/photos/36168640/pexels-photo-36168640.jpeg?auto=compress&cs=tinysrgb&w=1000", "lead": "Детские площадки и уличные тренажёры для дома, двора и базы отдыха.", "lead_ky": "Үй, короо жана эс алуу базасы үчүн балдар аянтчалары жана көчө машыгуу жабдуулары.", "text": "Проектируем и ставим детские площадки и уличные спортивные комплексы: горки, качели, лазалки, турники и тренажёры. Подбираем безопасное покрытие и надёжно бетонируем опоры.", "text_ky": "Балдар аянтчаларын жана көчө спорт комплекстерин долбоорлоп, орнотобуз: тайгаланчыктар, селкинчектер, чыгуучу тосмолор, турниктер жана машыгуу жабдуулары. Коопсуз жабууну тандап, тирөөчтөрдү бекем бетондойбуз.", "points": "Горки, качели, песочницы, лазалки\nТурники, брусья и уличные тренажёры\nРезиновое или травяное покрытие\nДля участков, дворов и баз отдыха", "points_ky": "Тайгаланчыктар, селкинчектер, кум салгычтар, чыгуучу тосмолор\nТурниктер, брустар жана көчө машыгуу жабдуулары\nРезина же чөп жабуу\nУчастоктор, короолор жана эс алуу базалары үчүн", "works": [{"image": "https://images.pexels.com/photos/6150623/pexels-photo-6150623.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Уличная спортплощадка", "title_ky": "Көчө спорт аянтчасы", "note": "демо-фото", "note_ky": "демо-сүрөт"}, {"image": "https://images.pexels.com/photos/31853817/pexels-photo-31853817.jpeg?auto=compress&cs=tinysrgb&w=800", "title": "Уличный тренажёр", "title_ky": "Көчө машыгуу жабдуусу", "note": "демо-фото", "note_ky": "демо-сүрөт"}]}');
